// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 250000000e18);
        // owner (deployer = this contract) calls NETM
        c.NETM();
        vm.prank(address(this));
        bool ok;
        try c.transfer(actor, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.balanceOf(actor) == amount);
    }
}
